class Solution {
public:
    long long beautifulSubarrays(std::vector<int>& nums) {
        std::unordered_map<int, int> count;
        count[0] = 1;
        int pref = 0;
        long long ans = 0;
        for (int x : nums) {
            pref ^= x;
            ans += count[pref];
            count[pref]++;
        }
        return ans;
    }
};

class Solution {
    public long beautifulSubarrays(int[] nums) {
        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        count.put(0, 1);
        int pref = 0;
        long ans = 0;
        for (int x : nums) {
            pref ^= x;
            ans += count.getOrDefault(pref, 0);
            count.put(pref, count.getOrDefault(pref, 0) + 1);
        }
        return ans;
    }
}

var beautifulSubarrays = function(nums) {
    const count = new Map();
    count.set(0, 1);
    let pref = 0;
    let ans = 0;
    for (const x of nums) {
        pref ^= x;
        const c = count.get(pref) || 0;
        ans += c;
        count.set(pref, c + 1);
    }
    return ans;
};
